WITH payload AS (SELECT $payload$[{"name":"椿大神社","slug":"tsubaki-dai-jinja","prefecture":"三重県","prefecture_slug":"mie","municipality":"鈴鹿市","address":"三重県鈴鹿市山本町 1871","latitude":34.964594681,"longitude":136.451904133,"official_url":null,"history":"猿田彦大神は、往古より天照大神との幽契による御旨を、地上に実行される地祇の根本の神、即ち地球国土守護の神として、地球上に生きとし生けるものの平和と幸福を守導する「みちびきの祖神」として崇め奉られている。其の生命の平安を守護される御神徳として、特に地まつり（地鎮祭）・方災解除・厄祓い・土地・家屋敷・国土の守護が霊験あらたかとされていて、当社では神山高山・短山の「お清めの砂」をもって地鎮祭・家屋敷の祓い清めを行い、獅子舞神事による天下泰安の方除厄除祈祷を千三百年の伝統を誇り今日におよんでいますと伝えられています。伝承には諸説あります。","deities":["猿田彦大神"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=3021","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"猿田彦神社","slug":"saru-tabiko-jinja","prefecture":"三重県","prefecture_slug":"mie","municipality":"伊勢市","address":"三重県伊勢市宇治浦田 2-1-10","latitude":34.46705321,"longitude":136.720299752,"official_url":null,"history":"宇治土公 貞尚 啓行（みちひらき） ４月4・５日 御田祭５月５日 秋祭１１月４・５日 当社は玉串大内人たる宇治土公が、その祖先の猿田彦大神と大田命を祀り、古くから広く崇敬されて来た神社である。創祭年代は不詳であるが、往古来宇治土公家は祖神まつりを行い、建久年間（１１９０～１１９９）までは、現在地に近い中村町興玉の森で祀られたと伝えられると伝えられています。伝承には諸説あります。","deities":["猿田彦大神"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=2959","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"日吉大社","slug":"hiyoshi-taisha","prefecture":"滋賀県","prefecture_slug":"shiga","municipality":"大津市","address":"滋賀県大津市坂本5丁目1-1","latitude":35.071746938,"longitude":135.862175791,"official_url":null,"history":"日吉大社は、霊峰比叡を背にして、びわ湖を一望できる絶景の地にひろがりをみせています。その広大な神域は、うっそうたる樹林におおわれ、多くの社殿とともに神々しい雰囲気をかもしだしていますと伝えられています。伝承には諸説あります。","deities":["大己貴神","大山咋神"],"benefits":[],"lineages":["出雲系信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=5890","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"建部大社","slug":"takebe-taisha","prefecture":"滋賀県","prefecture_slug":"shiga","municipality":"大津市","address":"滋賀県大津市神領1丁目16-1","latitude":34.9735876,"longitude":135.913493795,"official_url":null,"history":"当社は古来建部大社、建部大明神などど称え、延喜式内名神大社に列し、又近江国の一之宮として朝野の崇敬篤く、長い歴史と由緒を持つ全国屈指の古社である。御祭神日本武尊は御年僅に十六才にて熊襲を誅し、更に東夷を平定され、遂に３２才にして伊勢の能褒野に於て崩御されましたが、父君景行天皇は尊の死をいたく歎かれ御名代として建部を定め４６年神勅により御妃布多遅比売命（父は近江安国造）が、御子稲依別王と共に住われた神崎郡建部の郷（御名代の地）に尊の神霊を奉斎されたのが当社の草創であって、その後天武天皇白鳳四年当時近江国府の所在地であった当瀬田の地に迂祀し、近江一之宮（其の国を代表する第一位の神社）として崇め奉ったのが現在の当大社であると伝えられています。伝承には諸説あります。","deities":["日本武尊"],"benefits":[],"lineages":["日本武尊信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=5908","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"多賀大社","slug":"taga-taisha","prefecture":"滋賀県","prefecture_slug":"shiga","municipality":"犬上郡多賀町","address":"滋賀県犬上郡多賀町多賀604","latitude":35.225249088,"longitude":136.29067678,"official_url":null,"history":"この男女二柱の大神は、はじめて夫婦の道をおこされ、わが国土と万有の神神と、その主宰神としての天照大神をお生みになられましたので昔から、わが日本国の祖神さまと仰がれ奈良時代の初めにできた「古事記」には、すでに淡海の多賀に鎮座という記事が見えています。そこで早くより朝野尊崇あつく、延命長寿の守護神を信仰されてきました数数の霊験は、社蔵の古文書やご宝物、また境内にのこる寿命石、太閤蔵、文部省指定の各勝「奥書院庭園」などが明らかに物語っておりますと伝えられています。伝承には諸説あります。","deities":["伊邪那岐大神","伊邪那美大神"],"benefits":[],"lineages":[],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=5993","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"伏見稲荷大社","slug":"fushimi-inari-taisha","prefecture":"京都府","prefecture_slug":"kyoto","municipality":"京都市","address":"京都府京都市伏見区深草藪之内68","latitude":34.967150607,"longitude":135.773200174,"official_url":null,"history":null,"deities":["宇迦之御魂大神"],"benefits":[],"lineages":["稲荷信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=8733","source_type":"shrine_association","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"八坂神社","slug":"yasakajinja","prefecture":"京都府","prefecture_slug":"kyoto","municipality":"京都市","address":"京都府京都市東山区祇園町北側625","latitude":35.0036027,"longitude":135.7782611,"official_url":null,"history":"八坂神社は明治元年まで祇園社と称していたので、祇園さんの名で親しまれ信仰されている。社伝によると八坂神社は斉明天皇２年（６５６）高麗より来朝せる調進副使の伊利之使主（いりしおみ）が新羅国牛頭山（ごずさん）にます素戔嗚尊を山城国愛宕（おたぎ）郡八坂郷に祀り、八坂造の姓を賜わったのに始まると伝えられています。伝承には諸説あります。","deities":["素戔嗚尊"],"benefits":[],"lineages":["祇園信仰"],"sources":[{"name":"皇學館大学・県神社庁協力「新全国神社検索」","url":"https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=4499","source_type":"shrine_association","field_n