tmap.org/?mlat=34.87966667&mlon=135.70005556&zoom=18","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]},{"name":"粟鹿神社","slug":"awaga-jinja","prefecture":"兵庫県","prefecture_slug":"hyogo","municipality":"朝来市","address":"兵庫県朝来市山東町粟鹿2152","latitude":35.300819950784,"longitude":134.905008289453,"official_url":null,"history":null,"deities":["彦火火出見命"],"benefits":[],"lineages":[],"sources":[{"name":"粟鹿神社 公式サイト","url":"https://www.hyogo-c.ed.jp/~rekihaku-bo/historystation/trip/html/086/086.html","source_type":"government","field_name":"shrine_information","notes":"神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"},{"name":"座標参照・地図情報","url":"https://www.openstreetmap.org/?mlat=35.300819950784&mlon=134.905008289453&zoom=18","source_type":"other","field_name":"coordinates","notes":"住所・自治体と座標を照合し、地図上の位置確認に使用。"}]}]$payload$::jsonb AS value), incoming AS (SELECT * FROM jsonb_to_recordset((SELECT value FROM payload)) AS x(name text,slug text,prefecture text,prefecture_slug text,municipality text,address text,latitude double precision,longitude double precision,official_url text,history text,deities text[],benefits text[],lineages text[],sources jsonb)), pref_upsert AS (INSERT INTO public.prefectures(name,slug) SELECT DISTINCT prefecture,prefecture_slug FROM incoming ON CONFLICT (slug) DO UPDATE SET name=excluded.name RETURNING id,name), municipality_upsert AS (INSERT INTO public.municipalities(prefecture_id,name) SELECT DISTINCT p.id,i.municipality FROM incoming i JOIN pref_upsert p ON p.name=i.prefecture ON CONFLICT (prefecture_id,name) DO UPDATE SET name=excluded.name RETURNING id,prefecture_id,name), shrine_upsert AS (INSERT INTO public.shrines(name,slug,prefecture_id,municipality_id,address,location,official_url,history,is_published) SELECT i.name,i.slug,p.id,m.id,i.address,ST_SetSRID(ST_MakePoint(i.longitude,i.latitude),4326)::geography,i.official_url,i.history,true FROM incoming i JOIN pref_upsert p ON p.name=i.prefecture JOIN municipality_upsert m ON m.prefecture_id=p.id AND m.name=i.municipality ON CONFLICT (slug) DO UPDATE SET name=excluded.name,prefecture_id=excluded.prefecture_id,municipality_id=excluded.municipality_id,address=excluded.address,location=excluded.location,official_url=COALESCE(excluded.official_url,public.shrines.official_url),history=COALESCE(excluded.history,public.shrines.history),is_published=true,updated_at=now() RETURNING id,slug), source_rows AS (SELECT DISTINCT i.slug,s.name,s.url,s.source_type,s.field_name,s.notes FROM incoming i CROSS JOIN LATERAL jsonb_to_recordset(i.sources) AS s(name text,url text,source_type text,field_name text,notes text) WHERE s.url IS NOT NULL), source_upsert AS (INSERT INTO public.sources(name,url,source_type,last_verified_at,notes) SELECT s.name,s.url,s.source_type::public.source_type,DATE '2026-10-01',s.notes FROM (SELECT DISTINCT name,url,source_type,notes FROM source_rows) s WHERE NOT EXISTS (SELECT 1 FROM public.sources old WHERE old.name=s.name AND old.url=s.url) RETURNING id,name,url), source_records AS (SELECT id,name,url FROM source_upsert UNION ALL SELECT old.id,old.name,old.url FROM public.sources old JOIN (SELECT DISTINCT name,url FROM source_rows) x ON x.name=old.name AND x.url=old.url), source_links AS (INSERT INTO public.shrine_sources(shrine_id,source_id,field_name) SELECT DISTINCT sh.id,src.id,s.field_name FROM source_rows s JOIN shrine_upsert sh ON sh.slug=s.slug JOIN source_records src ON src.name=s.name AND src.url=s.url ON CONFLICT (shrine_id,source_id) DO UPDATE SET field_name=COALESCE(excluded.field_name,public.shrine_sources.field_name) RETURNING shrine_id), deity_links AS (INSERT INTO public.shrine_deities(shrine_id,deity_id,role,display_order) SELECT DISTINCT sh.id,d.id,'principal'::public.shrine_deity_role,0 FROM incoming i JOIN shrine_upsert sh ON sh.slug=i.slug CROSS JOIN LATERAL unnest(COALESCE(i.deities,ARRAY[]::text[])) raw(name) JOIN LATERAL (SELECT de.id FROM public.deities de WHERE de.name=raw.name OR raw.name=ANY(de.aliases) ORDER BY (de.name=raw.name) DESC,de.slug LIMIT 1) d ON true ON CONFLICT (shrine_id,deity_id) DO UPDATE SET role='principal'::public.shrine_deity_role RETURNING shrine_id,deity_id), shrine_lineage_links AS (INSERT INTO public.shrine_lineages(shrine_id,lineage_id) SELECT DISTINCT sh.id,l.id FROM incoming i JOIN shrine_upsert sh ON sh.slug=i.slug CROSS JOIN LATERAL unnest(COALESCE(i.lineages,ARRAY[]::text[])) ln(name) JOIN public.lineages l ON l.name=ln.name ON CONFLICT DO NOTHING RETURNING shrine_id,lineage_id), shrine_benefit_links AS (INSERT INTO public.shrine_benefits(shrine_id,benefit_id,description) SELECT DISTINCT sh.id,b.id,'出典に記された信仰上の願意の一例です。宗教的効能や結果を保証するものではありません。' FROM incoming i JOIN shrine_upsert sh ON sh.slug=i.slug CROSS JOIN LATERAL unnest(COALESCE(i.benefits,ARRAY[]::text[])) bn(name) JOIN public.benefits b ON b.name=bn.name ON CONFLICT (shrine_id,benefit_id) DO UPDATE SET description=excluded.description RETURNING shrine_id,benefit_id), inferred_deity_benefits AS (INSERT INTO public.deity_benefits(deity_id,benefit_id) SELECT DISTINCT dl.deity_id,sb.benefit_id FROM deity_links dl JOIN shrine_benefit_links sb ON sb.shrine_id=dl.shrine_id ON CONFLICT DO NOTHING RETURNING deity_id,benefit_id) SELECT jsonb_build_object('shrines_upserted',(SELECT count(*) FROM shrine_upsert),'sources_added',(SELECT count(*) FROM source_upsert),'source_links',(SELECT count(*) FROM source_links),'deity_links',(SELECT count(*) FROM deity_links),'lineage_links',(SELECT count(*) FROM shrine_lineage_links),'benefit_links',(SELECT count(*) FROM shrine_benefit_links),'deity_benefit_links',(SELECT count(*) FROM inferred_deity_benefits)) AS result;
